	(73, NULL, 47, 'Áo sơ mi kẻ sọc hồng tay phồng', '{"v":1,"intro":"Dáng áo sơ mi cổ trụ nhẹ nhàng kết hợp tay phồng tiểu thư, điểm nhấn nhún lưng tinh tế phía sau giúp che khuyết điểm và tạo độ bồng bềnh thanh lịch. Vải sơ mi cao cấp, mềm mịn, thấm hút mồ hôi tốt, ít nhăn và đứng form","highlights":["comfort","light","breathable"],"material":"","fit":"","suitable":"","features":"","care":"","returns":""}', 'ACTIVE'),
	(74, NULL, 49, 'Chân váy tầng ren thêu trắng', '{"v":1,"intro":"Chân váy dáng dài xếp tầng bồng bềnh với chất liệu vải cotton trắng đục lỗ hoa văn tinh tế. Kiểu dáng công chúa thanh lịch, trẻ trung, cực kỳ thích hợp cho những buổi hẹn hò cuối tuần hoặc các chuyến dã ngoại ngoài trời","highlights":["quickdry","breathable","comfort"],"material":"","fit":"","suitable":"","features":"","care":"","returns":""}', 'ACTIVE'),
	(75, NULL, 49, 'Chân váy denim xếp ly kèm thắt lưng', '{"v":1,"intro":"Chân váy denim tối màu cá tính kết hợp kiểu dáng xếp ly trẻ trung mang hơi hướng học đường. Đi kèm thắt lưng da nâu thanh mảnh và lớp viền ren lót nhẹ nhàng phía trong gấu váy, tạo nên sự giao thoa hoàn hảo giữa nét cổ điển và hiện đại","highlights":["durable"],"material":"","fit":"","suitable":"","features":"","care":"","returns":""}', 'ACTIVE'),
	(76, NULL, 52, 'Áo thun tay dài kẻ sọc', '{"v":1,"intro":"Chất liệu cotton mềm mại, thoáng mát, dễ dàng phối cùng quần jeans hoặc chân váy cho trang phục hàng ngày","highlights":["comfort","breathable","quickdry","stretch","durable","easywash"],"material":"","fit":"","suitable":"","features":"","care":"","returns":""}', 'ACTIVE'),
